#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "jacobi-1d.h"


/* Array initialization. */
static
void init_array (int n,
		 DATA_TYPE POLYBENCH_1D(A,N,n),
		 DATA_TYPE POLYBENCH_1D(B,N,n))
{
  int i;

  for (i = 0; i < n; i++)
    {
      A[i] = ((DATA_TYPE) i+ 2) / n;
      B[i] = ((DATA_TYPE) i+ 3) / n;
    }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_1D(A,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("A");
  for (i = 0; i < n; i++)
    {
      if (i % 20 == 0) fprintf(POLYBENCH_DUMP_TARGET, "\n");
      fprintf(POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i]);
    }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimizations applied:
   - Use restrict-qualified local aliases for A and B to aid vectorization.
   - Hoist loop-invariant quantities (_PB_N, _PB_TSTEPS, constant factor)
     out of the loops to reduce redundant work.
   - Optional OpenMP parallelization over the spatial dimension (i-loop).
     If compiled without -fopenmp, the pragmas are ignored and the code
     runs sequentially with identical semantics.
   - Use a compiler hint (#pragma GCC ivdep) to safely enable more
     aggressive vectorization in the innermost loops.
*/
static
void __attribute__((flatten, noinline))
kernel_jacobi_1d(int tsteps,
                 int n,
                 DATA_TYPE POLYBENCH_1D(A,N,n),
                 DATA_TYPE POLYBENCH_1D(B,N,n))
{
  /* Create local restrict-qualified pointers to help the optimizer.
     PolyBench allocates A and B separately, so they never alias. */
  DATA_TYPE * __restrict a = A;
  DATA_TYPE * __restrict b = B;

  /* Hoist loop bounds and constants out of the loops. */
  const int time_steps = _PB_TSTEPS;
  const int n_inner    = _PB_N;
  const int imax       = n_inner - 1;         /* last updated index is imax-1 */
  const DATA_TYPE c    = (DATA_TYPE)0.33333;  /* preserve original constant */

#pragma scop
  /* Parallelize over the spatial dimension. Time-stepping (t) remains
     strictly sequential to preserve the original dependence pattern.
     When OpenMP is not enabled, this pragma is ignored and the block
     executes as a normal compound statement. */
#pragma omp parallel default(none) shared(a,b,time_steps,n_inner,imax,c)
  {
    for (int t = 0; t < time_steps; ++t)
    {
      /* First sweep: update B from A.
         Each iteration of the i-loop is independent, so it is safe to
         parallelize and vectorize. */
#pragma omp for schedule(static)
#pragma GCC ivdep
      for (int i = 1; i < imax; ++i)
        b[i] = c * (a[i - 1] + a[i] + a[i + 1]);

      /* Implicit barrier here (end of omp for) ensures all B[i] are
         computed for this time step before updating A. */

      /* Second sweep: update A from B. */
#pragma omp for schedule(static)
#pragma GCC ivdep
      for (int i = 1; i < imax; ++i)
        a[i] = c * (b[i - 1] + b[i] + b[i + 1]);

      /* Another implicit barrier at the end of this omp for ensures
         A is fully updated for this time step before the next t. */
    }
  }
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int tsteps = TSTEPS;

  /* Variable declaration/allocation. */
  POLYBENCH_1D_ARRAY_DECL(A, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(B, DATA_TYPE, N, n);

  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_jacobi_1d(tsteps, n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);

  return 0;
}
