  const DATA_TYPE offsetA = (DATA_TYPE)2.0 * inv_n;
  const DATA_TYPE offsetB = (DATA_TYPE)3.0 * inv_n;

  /* Parallelize initialization for large n when OpenMP is enabled.
     Without -fopenmp, this pragma is ignored and we get a simple
     sequential loop identical in semantics to the original code. */
