  for (i = 0; i < n; i++)
  {
    DATA_TYPE base = (DATA_TYPE)i * inv_n;
    a[i] = base + offsetA; /* ((DATA_TYPE)i + 2) / n in algebraic form */
    b[i] = base + offsetB; /* ((DATA_TYPE)i + 3) / n in algebraic form */
  }
}


